    id uuid, name text, cuisine text, description text, address text,
    latitude double precision, longitude double precision, rating double precision,
    price_level integer, opening_hours text, tags text[], is_halal boolean,
    phone text, website text, review_count integer, google_place_id text,
    source_url text, source_name text, source_file text, business_status text
);

-- Append only. Do not overwrite existing manually maintained profiles, ratings,
-- or HALAL flags. A same-name existing entry within 50 m is treated as a match.
WITH inserted AS (
    INSERT INTO public.restaurants (
        id, name, cuisine, description, address, latitude, longitude,
        rating, price_level, opening_hours, tags, is_halal,
        phone, website, review_count, google_place_id, source_url,
        source_name, source_file, business_status, imported_at
    )
    SELECT i.id, i.name, i.cuisine, i.description, i.address, i.latitude, i.longitude,
        i.rating, i.price_level, i.opening_hours, i.tags, i.is_halal,
        i.phone, i.website, i.review_count, i.google_place_id, i.source_url,
        i.source_name, i.source_file, i.business_status, now()
    FROM dinefinder_outscraper_import i
    WHERE NOT EXISTS (
        SELECT 1 FROM public.restaurants r
        WHERE r.id = i.id OR r.google_place_id = i.google_place_id OR (
            lower(regexp_replace(btrim(r.name), '\s+', ' ', 'g')) =
                lower(regexp_replace(btrim(i.name), '\s+', ' ', 'g'))
            AND extensions.st_dwithin(r.location,
                extensions.st_setsrid(extensions.st_makepoint(i.longitude, i.latitude),4326)::extensions.geography, 50)
        )
    )
    ON CONFLICT (id) DO NOTHING
    RETURNING id
)
SELECT (SELECT count(*) FROM dinefinder_outscraper_import) AS candidate_listings,
       count(*) AS inserted_this_run FROM inserted;
NOTIFY pgrst, 'reload schema';
COMMIT;

SELECT count(*) AS total_restaurant_records FROM public.restaurants;
